            args(&["start", "--rehearsal-place", place.to_str().expect("utf-8")]).expect("parses");
        let rehearsal = w.run(&line).expect("the rehearsal stamps");
        let stamp = rehearsal.stamp.expect("a stamp");
        assert_eq!((stamp.commit, stamp.clean), (None, false));
        assert!(reuse_copy(&rehearsal.dir, None).is_ok());
        let error = error_of(reuse_copy(&rehearsal.dir, Some(HEAD)));
        assert!(error.contains("built at no commit"), "{error}");
        let order = rehearsal.launch.expect("an order");
        assert_eq!(order["rehearsal"], json!(true));
        assert_eq!(order["offscreen"], json!(true));
