    #[test]
    fn the_app_is_started_directly_never_through_a_wrapper() {
        for rehearsal in [false, true] {
            let (dir, launch) = fake_profile(rehearsal);
            let copy = dir.copy_file();
            let cmd = app_command(&copy, &dir, &launch, None, &[]).expect("a command");
            assert_eq!(Path::new(cmd.get_program()), copy.as_path());
            let args: Vec<_> = cmd.get_args().map(|a| a.to_string_lossy()).collect();
            assert_eq!(args[0], "--dev-control");
            assert_eq!(args.len(), if rehearsal { 2 } else { 1 }, "{args:?}");
            assert_eq!(launch["bin"], json!(copy));
            // The tool names what it set, never through a program that would hold it.
            for wrapper in ["kcap", "systemd-run", "env", "timeout", "sh", "bash"] {
                assert_ne!(
                    Path::new(cmd.get_program())
                        .file_name()
                        .and_then(|n| n.to_str()),
                    Some(wrapper)
                );
            }
        }
    }

    #[test]
    fn a_real_start_keeps_the_qr_and_desktop_in_the_app() {
        let inherited: Vec<OsString> = [
            REHEARSAL_ENV,
            "KOURIER_SIGNAL_ENV",
            "KOURIER_FAILPOINT",
            TAIL_ENV,
            "PATH",
            "HOME",
        ]
        .iter()
        .map(OsString::from)
        .collect();
        let (dir, launch) = fake_profile(false);
        let cmd = app_command(&dir.copy_file(), &dir, &launch, None, &inherited).expect("command");
        let env = envs_of(&cmd);
        // Every inherited KOURIER_* is taken out; the fake network is never in a real run's place.
        for name in [REHEARSAL_ENV, "KOURIER_SIGNAL_ENV", "KOURIER_FAILPOINT"] {
            assert_eq!(env.get(name), Some(&None), "{name} must be removed");
        }
        let set = |name: &str| env.get(name).cloned().flatten();
        assert_eq!(set("KOURIER_HOME").as_deref(), Some("/fake/profile"));
        assert_eq!(set("KOURIER_DEV_KEYRING").as_deref(), Some("passphrase"));
        assert_eq!(set("KOURIER_DEV_NO_DUMP").as_deref(), Some("1"));
        assert_eq!(set("KOURIER_DEV_QR_URL").as_deref(), Some("0"));
        assert_eq!(set("KOURIER_DESKTOP").as_deref(), Some("0"));
        assert_eq!(set("KOURIER_LOG").as_deref(), Some(APP_LOG_FILTER));
        assert_eq!(set("QT_FORCE_STDERR_LOGGING").as_deref(), Some("1"));
        // Other variables are the user's: untouched, and a real run has a window.
        assert!(!env.contains_key("PATH") && !env.contains_key("HOME"));
        for name in ["QT_QPA_PLATFORM", "PULSE_SERVER", "KOURIER_SIGNAL_ENV_SET"] {
            assert!(set(name).is_none(), "{name}");
        }
        // The rehearsal: the fake network, no window, no sound.
        let (dir, launch) = fake_profile(true);
        let cmd = app_command(&dir.copy_file(), &dir, &launch, None, &inherited).expect("command");
        let env = envs_of(&cmd);
        let set = |name: &str| env.get(name).cloned().flatten();
        assert_eq!(set(REHEARSAL_ENV).as_deref(), Some("whatsapp"));
        assert_eq!(set("QT_QPA_PLATFORM").as_deref(), Some("offscreen"));
        assert!(
            set("PULSE_SERVER").is_some_and(|v| v.contains("/nonexistent/")),
            "{env:?}"
        );
        assert!(set("PIPEWIRE_REMOTE").is_some());
        assert_eq!(env.get("PULSE_RUNTIME_PATH"), Some(&None));
    }

    #[test]
    fn a_start_without_typed_digits_gets_a_tail_no_number_has() {
        let (dir, launch) = fake_profile(false);
        let inherited = [OsString::from(TAIL_ENV)];
        let value = |cmd: &Command| envs_of(cmd).get(TAIL_ENV).cloned().flatten();
        let cmd = app_command(&dir.copy_file(), &dir, &launch, None, &inherited).expect("command");
        let tail =
            value(&cmd).expect("the app is told a tail: without one it would link any phone");
        assert_eq!(tail, SENTINEL_TAIL);
        assert!(tail.len() == 15 && tail.bytes().all(|b| b == b'0'));
        // Typed digits pass as they are (the order says they were typed).
        let mut typed = launch.clone();
        typed["tail_typed"] = json!(true);
        let cmd = app_command(&dir.copy_file(), &dir, &typed, Some(TYPED_TAIL), &inherited)
            .expect("command");
        assert_eq!(value(&cmd).as_deref(), Some(TYPED_TAIL));
        // An order and a supervisor that disagree about the tail start nothing.
        assert!(app_command(&dir.copy_file(), &dir, &typed, None, &[]).is_err());
        let error = error_of(app_command(
            &dir.copy_file(),
            &dir,
            &launch,
            Some(TYPED_TAIL),
            &[],
        ));
        assert!(error.contains("disagree"), "{error}");
        assert!(!error.contains(TYPED_TAIL), "the error repeats the digits");
    }

    #[test]
    fn the_launch_is_described_by_names_and_never_by_values() {
        let (dir, launch) = fake_profile(false);
        let mut typed = launch.clone();
        typed["tail_typed"] = json!(true);
        let cmd =
            app_command(&dir.copy_file(), &dir, &typed, Some(TYPED_TAIL), &[]).expect("command");
        let text = describe_launch(&cmd);
        assert!(text.contains("--dev-control"), "{text}");
        for name in [TAIL_ENV, "KOURIER_HOME", "KOURIER_DEV_QR_URL"] {
            assert!(text.contains(name), "{name}: {text}");
        }
        for value in [TYPED_TAIL, "passphrase", SENTINEL_TAIL] {
            assert!(
                !text.contains(value),
                "the description shows {value}: {text}"
            );
        }
    }

