            let shared = Arc::clone(&w.shared);
            let feeder = std::thread::spawn(move || {
                assert!(until(10, || locked(&shared)
                    .events
                    .iter()
                    .any(|(_, e)| e["event"] == "login_qr")));
                locked(&shared).on_app_event(app_event(
                    "account_state",
                    json!({"account": 1, "conn": "restricted", "state": "active"}),
                ));
            });
            let end = run_link(&w);
            feeder.join().expect("thread");
            assert_eq!(end.status, 1, "{}", end.reason);
            assert!(end.reason.contains("halted (restricted)"), "{}", end.reason);
            assert!(until(10, || seen_by(&w.dir).iter().any(|c| c == "quit")));
